```yaml
name: Claude Code Review

on:
  pull_request:
    types: [opened, synchronize, ready_for_review, reopened]

concurrency:
  group: claude-review-${{ github.event.pull_request.number }}
  cancel-in-progress: true

permissions:
  pull-requests: write
  contents: read

jobs:
  review:
    if: github.event.pull_request.draft == false && github.actor != 'dependabot[bot]'
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Run Claude code review
        id: claude
        uses: anthropics/claude-code-base-action@beta
        env:
          ANTHROPIC_API_KEY: ${{ secrets.ANTHROPIC_API_KEY }}
        with:
          prompt_file: .cursor/commands/review-pr.md
          allowed_tools: cargo,yarn,git,gh
          max_turns: 5
          timeout_minutes: 30
          append_system_prompt: true

      - name: Post or update Claude review comment
        uses: actions/github-script@v6
        with:
          script: |
            const conclusion = `${{ steps.claude.outputs.conclusion }}`;
            if (!conclusion) {
              console.log('No conclusion from Claude.');
              return;
            }
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const issue_number = context.issue.number;
            const body = `## Claude Review\n\n${conclusion}`;
            const comments = await github.rest.issues.listComments({
              owner,
              repo,
              issue_number
            });
            const botComment = comments.data.find(c => c.user.login === 'github-actions[bot]' && c.body.includes('## Claude Review'));
            if (botComment) {
              await github.rest.issues.updateComment({
                owner,
                repo,
                comment_id: botComment.id,
                body
              });
            } else {
              await github.rest.issues.createComment({
                owner,
                repo,
                issue_number,
                body
              });
            }
